// Fixture key material, generated by `xray x25519` and `openssl rand -base64`.
// Nothing here is used anywhere real.
const (
	testRealityPrivate = "sCg4m4EzwI-ABTXkpBUlq7bXjvoGzOubGY3J8dhTL2o"
	testRealityPublic  = "EHrIxc9qujEbp1w115n8nf4aBgOZD45iSDc9dCwYwB8"
	testSS128          = "glwKkLUrNxQ4VbjbZG4svg=="
	testSS256          = "IJcUcdTlhkfRacXSeMtYDe9BCeOGk9ZvPligI6RNTxE="
	testLinkUUID       = "0f62f495-b5ca-4509-b6cd-54a040deafd5"
)

func ssLinkIn(id int64, port int) LinkIn {
	return LinkIn{Key: NewLinkKey(id), Port: port, Protocol: LinkProtocolSS2022,
		SS: &LinkSS{Method: "2022-blake3-aes-128-gcm", Password: testSS128}}
}

func ssLinkOut(id int64) LinkOut {
	return LinkOut{Key: NewLinkKey(id), Address: "exit.example.com", Port: 30001, Protocol: LinkProtocolSS2022,
		SS: &LinkSS{Method: "2022-blake3-aes-128-gcm", Password: testSS128}}
}

func realityLinkIn(id int64) LinkIn {
	return LinkIn{Key: NewLinkKey(id), Port: 30443, Protocol: LinkProtocolVLESSReality,
		Reality: &LinkRealityServer{UUID: testLinkUUID, PrivateKey: testRealityPrivate,
			Target: "www.example.com:443", ServerNames: []string{"www.example.com"}, ShortIDs: []string{"", "a1b2"}}}
}

func realityLinkOut(id int64) LinkOut {
	return LinkOut{Key: NewLinkKey(id), Address: "203.0.113.20", Port: 30443, Protocol: LinkProtocolVLESSReality,
		Reality: &LinkRealityClient{UUID: testLinkUUID, PublicKey: testRealityPublic,
			ServerName: "www.example.com", ShortID: "a1b2", Fingerprint: "chrome"}}
}

func TestLinkKeyIsItsOwnType(t *testing.T) {
	key := NewLinkKey(5)
	if key != "lnk_5" {
		t.Fatalf("minted %q", key)
	}
	if id, err := key.RowID(); err != nil || id != 5 {
		t.Fatalf("RowID = %d, %v", id, err)
	}
	if _, err := ListenerKey(key).RowID(); err == nil {
		t.Fatal("a link key parsed as a listener key")
	}
	if _, err := ForwardKey(key).RowID(); err == nil {
		t.Fatal("a link key parsed as a forward key")
	}
}

func TestValidateLinks(t *testing.T) {
	valid := &Transit{
		LinksIn:  []LinkIn{ssLinkIn(1, 30001), realityLinkIn(2)},
		LinksOut: []LinkOut{ssLinkOut(3), realityLinkOut(4)},
		Egress: []EgressBinding{
			{Listener: NewListenerKey(10), Link: NewLinkKey(3)},
			{Listener: NewListenerKey(11), Link: NewLinkKey(4)},
		},
	}
	if err := ValidateTransit(valid); err != nil {
		t.Fatalf("valid transit: %v", err)
	}
	ss256 := ssLinkOut(3)
	ss256.SS = &LinkSS{Method: "2022-blake3-aes-256-gcm", Password: testSS256}
	if err := ValidateLinkOut(ss256); err != nil {
		t.Fatalf("256-bit ss link: %v", err)
	}

	bad := map[string]func(*Transit){
		"same link on both sides":     func(tr *Transit) { tr.LinksOut[0].Key = NewLinkKey(1) },
		"duplicate out":               func(tr *Transit) { tr.LinksOut[1].Key = NewLinkKey(3) },
		"egress to an unknown link":   func(tr *Transit) { tr.Egress[0].Link = NewLinkKey(99) },
		"egress to an incoming link":  func(tr *Transit) { tr.Egress[0].Link = NewLinkKey(1) },
		"one listener two bindings":   func(tr *Transit) { tr.Egress[1].Listener = NewListenerKey(10) },
		"egress from a non-listener":  func(tr *Transit) { tr.Egress[0].Listener = "lnk_1" },
		"unknown protocol":            func(tr *Transit) { tr.LinksIn[0].Protocol = "wireguard" },
		"ss without credential":       func(tr *Transit) { tr.LinksIn[0].SS = nil },
		"ss with reality too":         func(tr *Transit) { tr.LinksIn[0].Reality = realityLinkIn(9).Reality },
		"ss legacy method":            func(tr *Transit) { tr.LinksIn[0].SS.Method = "aes-128-gcm" },
		"ss key of the wrong length":  func(tr *Transit) { tr.LinksIn[0].SS.Password = testSS256 },
		"ss key not base64":           func(tr *Transit) { tr.LinksIn[0].SS.Password = "not base64!" },
		"port zero":                   func(tr *Transit) { tr.LinksIn[0].Port = 0 },
		"noncanonical listen":         func(tr *Transit) { tr.LinksIn[0].Listen = "2001:0db8::1" },
		"reality private key padded":  func(tr *Transit) { tr.LinksIn[1].Reality.PrivateKey += "=" },
		"reality uppercase uuid":      func(tr *Transit) { tr.LinksIn[1].Reality.UUID = strings.ToUpper(testLinkUUID) },
		"reality target without port": func(tr *Transit) { tr.LinksIn[1].Reality.Target = "www.example.com" },
		"reality no server names":     func(tr *Transit) { tr.LinksIn[1].Reality.ServerNames = nil },
		"reality address server name": func(tr *Transit) { tr.LinksIn[1].Reality.ServerNames = []string{"203.0.113.1"} },
		"reality odd short id":        func(tr *Transit) { tr.LinksIn[1].Reality.ShortIDs = []string{"abc"} },
		"reality no short ids":        func(tr *Transit) { tr.LinksIn[1].Reality.ShortIDs = nil },
		"out address with port":       func(tr *Transit) { tr.LinksOut[0].Address = "exit.example.com:30001" },
		"out reality private key":     func(tr *Transit) { tr.LinksOut[1].Reality.PublicKey = "short" },
		"out unknown fingerprint":     func(tr *Transit) { tr.LinksOut[1].Reality.Fingerprint = "netscape" },
		"out uppercase short id":      func(tr *Transit) { tr.LinksOut[1].Reality.ShortID = "A1B2" },
	}
	for name, mutate := range bad {
		raw, _ := json.Marshal(valid)
		var copy Transit
		if err := json.Unmarshal(raw, &copy); err != nil {
			t.Fatal(err)
		}
		mutate(&copy)
		if err := ValidateTransit(&copy); err == nil {
			t.Errorf("%s: accepted", name)
		}
	}
}

// The entry never holds the exit's REALITY private key: the type it receives
// has no field for it, so no encoding of a LinkOut can carry one.
func TestLinkOutCannotCarryThePrivateKey(t *testing.T) {
	b, err := json.Marshal(realityLinkOut(1))
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(b), "private") {
		t.Fatalf("a LinkOut encodes a private key field: %s", b)
	}
	var probe LinkOut
	if err := json.Unmarshal([]byte(`{"key":"lnk_1","reality":{"private_key":"x"}}`), &probe); err != nil {
		t.Fatal(err)
	}
	b, _ = json.Marshal(probe)
	if strings.Contains(string(b), "private") {
		t.Fatal("a private key survived a LinkOut round trip")
	}
}

func TestTransitWithoutLinksKeepsItsEncoding(t *testing.T) {
	b, err := json.Marshal(Transit{Forwards: []Forward{validForward()}})
	if err != nil {
		t.Fatal(err)
	}
	for _, field := range []string{"links_in", "links_out", "egress"} {
		if strings.Contains(string(b), field) {
			t.Errorf("a forwards-only transit mentions %s: %s", field, b)
		}
	}
}

func TestLinkCountersAndObjects(t *testing.T) {
	report := NodeReport{
		AgentID: "a1", ProtocolVersion: ProtocolVersion1, Have: emptyHave(),
		Capabilities: []string{CapabilityTransitLink},
		LinkCounters: []LinkCounters{{Key: NewLinkKey(1), Present: true, UpBytes: 1, DownBytes: 2, CounterEpoch: 1}},
		Objects: []ObjectStatus{{
			Stream: StreamConfig, Key: string(NewLinkKey(1)), State: ObjectApplied, SinceVersion: Version{Epoch: 1, Version: 1},
		}},
	}
	if err := ValidateNodeReport(report); err != nil {
		t.Fatalf("full report with link counters and a link object: %v", err)
	}
	withoutCapability := report
	withoutCapability.Capabilities = nil
	if err := ValidateNodeReport(withoutCapability); err == nil {
		t.Error("link counters accepted without the capability")
	}
	partial := report
	partial.Partial = true
	partial.Objects = nil
	if err := ValidateNodeReportBase(partial); err == nil {
		t.Error("partial report carrying link counters accepted")
	}
	for name, counters := range map[string][]LinkCounters{
		"negative":  {{Key: NewLinkKey(1), UpBytes: -1}},
		"duplicate": {{Key: NewLinkKey(1)}, {Key: NewLinkKey(1)}},
		"wrong key": {{Key: "fwd_1"}},
	} {
		bad := report
		bad.LinkCounters = counters
		if err := ValidateNodeReportBase(bad); err == nil {
			t.Errorf("%s link counters accepted", name)
		}
	}
}
